      "type": "object",
      "properties": {
        "operations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "incomingItemId": {
                "type": "string"
              },
              "kind": {
                "type": "string"
              },
              "statement": {
                "type": "string"
              },
              "targetEntityId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "featureKey": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "claimIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": "string"
              },
              "relatedRejectionId": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
